204	    const count = (db.prepare("SELECT COUNT(*) as c FROM donations WHERE completed_at >= ? AND completed_at <= ?").get(dayStart.toISOString(), dayEnd.toISOString()) as any).c;
205	    weekly.push({ date: dayStart.toISOString().slice(0, 10), count });
