207	  // Top food types donated
208	  const foodTypes = db.prepare("SELECT food_type, COUNT(*) as c FROM donations GROUP BY food_type ORDER BY c DESC").all() as any[];
209	  // Total portions donated
210	  const totalPortions = (db.prepare("SELECT COALESCE(SUM(portion_count), 0) as t FROM donations WHERE status = 'completed'").get() as any).t;
211	  // Total protein distributed
