216	// --- Donations ---
217	apiRouter.post("/donations", authMiddleware, requireRole("donor"), validate(createDonationSchema), (req: AuthRequest, res: Response) => {
218	  const d = req.body;
219	  const result = db.prepare(`INSERT INTO donations (donor_id, food_name, food_type, portion_count, protein_per_portion, calorie_per_portion, iron_mg, vitamin_c_mg, valid_until, pickup_latitude, pickup_longitude, notes, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
220	    .run(req.user!.id, d.food_name, d.food_type, parseInt(d.portion_count), parseFloat(d.protein_per_portion), parseFloat(d.calorie_per_portion), d.iron_mg ? parseFloat(d.iron_mg) : null, d.vitamin_c_mg ? parseFloat(d.vitamin_c_mg) : null, new Date(Date.now() + parseInt(d.hours_valid) * 3600000).toISOString(), parseFloat(d.pickup_latitude), parseFloat(d.pickup_longitude), d.notes, new Date().toISOString());
221	  const donId = result.lastInsertRowid as number;
222	  calculateTopsisForDonation(donId);
223	  // Notify all potential recipients about new donation
224	  const recipients = db.prepare("SELECT id FROM users WHERE role = 'recipient' AND status = 'verified'").all() as any[];
225	  recipients.forEach((r: any) => {
226	    const nId = db.prepare("INSERT INTO notifications (user_id, title, message, type, is_read, related_donation_id, created_at) VALUES (?, ?, ?, 'donation_available', 0, ?, ?)").run(r.id, "Donasi Tersedia!", `Donasi ${d.food_name} sejumlah ${d.portion_count} porsi telah dipublikasikan. Segera cek dashboard Anda!`, donId, new Date().toISOString()).lastInsertRowid;
227	    const n = db.prepare("SELECT * FROM notifications WHERE id = ?").get(nId) as any;
