type LogLevel = "debug" | "info" | "warn" | "error";

const LOG_LEVELS: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

const currentLevel: LogLevel = (process.env.LOG_LEVEL as LogLevel) || (process.env.NODE_ENV === "production" ? "info" : "debug");

function shouldLog(level: LogLevel): boolean {
  return LOG_LEVELS[level] >= LOG_LEVELS[currentLevel];
}

function formatMessage(level: LogLevel, message: string, meta?: Record<string, any>): string {
  if (process.env.NODE_ENV === "production") {
    return JSON.stringify({
      timestamp: new Date().toISOString(),
      level,
      message,
      ...meta,
    });
  }
  const metaStr = meta ? ` ${JSON.stringify(meta)}` : "";
  return `[${new Date().toISOString()}] [${level.toUpperCase()}] ${message}${metaStr}`;
}

export const logger = {
  debug: (message: string, meta?: Record<string, any>) => {
    if (shouldLog("debug")) console.log(formatMessage("debug", message, meta));
  },
  info: (message: string, meta?: Record<string, any>) => {
    if (shouldLog("info")) console.log(formatMessage("info", message, meta));
  },
  warn: (message: string, meta?: Record<string, any>) => {
    if (shouldLog("warn")) console.warn(formatMessage("warn", message, meta));
  },
  error: (message: string, meta?: Record<string, any>) => {
    if (shouldLog("error")) console.error(formatMessage("error", message, meta));
  },
};

