const BASE_URL = typeof import.meta !== 'undefined' && (import.meta as any).env?.VITE_API_URL || "";

export const api = {
  fetchJSON: async (url: string, options?: RequestInit) => {
    const fullUrl = url.startsWith("/api") ? `${BASE_URL}${url}` : url;
    const res = await fetch(fullUrl, { ...options, credentials: "include" });
    if (!res.ok) {
      let message = "Something went wrong";
      try { const data = await res.json(); message = data.message || message; } catch {}
      throw new Error(message);
    }
    return res.json();
  }
};

