39	      { key: "business_name", fn: () => validateRequired(form.business_name, "Nama Bisnis") },
40	      { key: "email", fn: () => validateEmail(form.email) },
41	      { key: "password", fn: () => validatePassword(form.password) },
42	      { key: "address", fn: () => validateRequired(form.address, "Alamat") },
43	    ];
44	    const newErrors: FieldErrors = {};
45	    let valid = true;
46	    fields.forEach(f => {
47	      const r = f.fn();
