1	import { useState, useEffect, useCallback } from "react";
2	import { useNavigate } from "react-router-dom";
3	import { api } from "../lib/api";
4	import { Donation } from "../types";
5	import { useAuth } from "../contexts/AuthContext";
6	import { LiveTrackingModal } from "../components/LiveTrackingModal";
7	import { ProfileModal } from "../components/ProfileModal";
8	import { EmptyState } from "../components/EmptyState";
9	import { LoadingSpinner } from "../components/LoadingSpinner";
10	import {
11	  Star, Package, Clock, Plus, Activity, CheckCircle, Truck, TrendingUp,
12	  Bell, Dices, Book, Upload
13	} from "lucide-react";
14	import toast from "react-hot-toast";
15	import { formatDistanceToNow } from "date-fns";
16	import { id as idLocale } from "date-fns/locale";
17	import { motion, AnimatePresence } from "motion/react"
18	import { SEO } from "../components/SEO";
19	
20	type FilterTab = "all" | "active" | "claimed" | "completed";
21	
22	export function DonorDashboard() {
23	  const [donations, setDonations] = useState<Donation[]>([]);
24	  const [trackingData, setTrackingData] = useState<any>(null);
25	  const [showProfile, setShowProfile] = useState(false);
26	  const [reviews, setReviews] = useState<any[]>([]);
27	  const [loading, setLoading] = useState(true);
28	  const [filterTab, setFilterTab] = useState<FilterTab>("all");
29	  const [showForm, setShowForm] = useState(false);
30	  const [formStep, setFormStep] = useState(1);
31	  const [notifications, setNotifications] = useState<any[]>([]);
32	  const [showNotif, setShowNotif] = useState(false);
33	  const [badges, setBadges] = useState<any[]>([]);
34	  const nav = useNavigate();
35	  const { user, profile, loading: authLoading, logout, refresh } = useAuth();
36	
37	  const [form, setForm] = useState({
38	    food_name: "", food_type: "makanan_berat", portion_count: "", protein_per_portion: "",
39	    calorie_per_portion: "", hours_valid: "6", pickup_latitude: 0, pickup_longitude: 0,
40	    notes: "", iron_mg: "", vitamin_c_mg: "", photo_url: ""
41	  });
42	  const [uploading, setUploading] = useState(false);
43	
44	  useEffect(() => {
45	    if (profile) setForm(f => ({ ...f, pickup_latitude: profile.latitude, pickup_longitude: profile.longitude }));
46	  }, [profile]);
47	
48	  useEffect(() => {
49	    if (!authLoading && (!user || user.role !== "donor")) nav("/login");
50	  }, [authLoading, user]);
51	
52	  if (authLoading || !user) return null;
53	
54	  const loadDonations = async () => {
55	    try {
56	      const [data, donorReviews, notifs, bdgs] = await Promise.all([
57	        api.fetchJSON(`/api/donations?donor_id=${user.id}`),
58	        api.fetchJSON(`/api/donors/${user.id}/reviews`),
59	        api.fetchJSON(`/api/notifications?user_id=${user.id}`),
60	        api.fetchJSON(`/api/donors/${user.id}/badges`),
61	      ]);
62	      setDonations(data);
63	      setReviews(donorReviews);
64	      setNotifications(notifs);
65	      setBadges(bdgs);
66	    } finally {
67	      setLoading(false);
68	    }
69	  };
70	
71	  useEffect(() => { loadDonations(); }, []);
72	
73	  // Real-time notifications via SSE
74	  useEffect(() => {
75	    if (!user?.id) return;
76	    const es = new EventSource(`/api/notifications/subscribe?user_id=${user.id}`);
77	    es.onmessage = (e) => {
78	      if (e.data === "connected") return;
79	      try {
80	        const data = JSON.parse(e.data);
81	        setNotifications(prev => [data, ...prev]);
82	        toast.success(data.title || "Notifikasi baru!");
83	      } catch {}
84	    };
85	    return () => es.close();
86	  }, [user?.id]);
87	
88	  // Fallback polling
89	  useEffect(() => {
90	    const timer = setInterval(async () => {
91	      try {
92	        const notifs = await api.fetchJSON(`/api/notifications?user_id=${user.id}`);
93	        setNotifications(notifs);
94	      } catch {}
95	    }, 30000);
96	    return () => clearInterval(timer);
97	  }, [user.id]);
98	
99	  // Food catalog for quick selection
100	  const [showCatalog, setShowCatalog] = useState(false);
101	  const FOOD_CATALOG = [
102	    { name: "Nasi Kotak", type: "makanan_berat", protein: 8, calorie: 500, iron: 1.5, vitamin_c: 0 },
103	    { name: "Nasi Kuning", type: "makanan_berat", protein: 7, calorie: 480, iron: 1.2, vitamin_c: 0 },
104	    { name: "Ayam Goreng (porsi)", type: "lauk_protein", protein: 25, calorie: 350, iron: 2.0, vitamin_c: 0 },
105	    { name: "Telur Rebus (per butir)", type: "lauk_protein", protein: 6, calorie: 70, iron: 0.8, vitamin_c: 0 },
106	    { name: "Sayur Sop (porsi)", type: "sayur", protein: 2, calorie: 60, iron: 0.5, vitamin_c: 5 },
107	    { name: "Capcay (porsi)", type: "sayur", protein: 3, calorie: 80, iron: 1.0, vitamin_c: 8 },
108	    { name: "Buah Potong", type: "snack", protein: 1, calorie: 100, iron: 0.3, vitamin_c: 15 },
109	    { name: "Roti Isi", type: "snack", protein: 5, calorie: 200, iron: 1.0, vitamin_c: 0 },
110	    { name: "Air Mineral (botol)", type: "minuman", protein: 0, calorie: 0, iron: 0, vitamin_c: 0 },
111	    { name: "Susu Kotak", type: "minuman", protein: 7, calorie: 150, iron: 0.5, vitamin_c: 2 },
112	  ];
113	
114	  const selectFromCatalog = (item: typeof FOOD_CATALOG[0]) => {
115	    setForm({
116	      ...form,
117	      food_name: item.name,
118	      food_type: item.type,
119	      protein_per_portion: item.protein.toString(),
120	      calorie_per_portion: item.calorie.toString(),
121	      iron_mg: item.iron > 0 ? item.iron.toString() : "",
122	      vitamin_c_mg: item.vitamin_c > 0 ? item.vitamin_c.toString() : "",
123	    });
124	    setShowCatalog(false);
125	    setFormStep(2);
126	  };
127	
128	  const handleSubmit = async (e: any) => {
129	    e.preventDefault();
130	    try {
131	      await api.fetchJSON("/api/donations", {
132	        method: "POST", headers: { "Content-Type": "application/json" },
133	        body: JSON.stringify({ ...form, donor_id: user.id })
134	      });
135	      toast.success("Donasi berhasil dipublikasikan!");
136	      loadDonations();
137	      setForm({ ...form, food_name: "", portion_count: "", protein_per_portion: "", calorie_per_portion: "", iron_mg: "", vitamin_c_mg: "" });
138	      setShowForm(false);
139	      setFormStep(1);
140	    } catch (err: any) { toast.error(err.message || "Gagal mencatat donasi"); }
141	  };
142	
143	  const handleComplete = async (donationId: number) => {
144	    try {
145	      await api.fetchJSON(`/api/donations/${donationId}/complete`, { method: "POST" });
146	      toast.success("Donasi berhasil diselesaikan!");
147	      loadDonations();
148	    } catch (err: any) { toast.error(err.message || "Gagal menyelesaikan donasi"); }
149	  };
150	
151	  const filtered = donations.filter(d => {
152	    if (filterTab === "active") return d.status === "active";
153	    if (filterTab === "claimed") return d.status === "claimed";
154	    if (filterTab === "completed") return d.status === "completed";
155	    return true;
156	  });
157	
158	  const statusCount = (status: string) => donations.filter(d => d.status === status).length;
159	  const totalPorsi = donations.filter(d => d.status !== "expired").reduce((a, d) => a + (d.portion_count || 0), 0);
160	  const avgRating = reviews.length > 0 ? (reviews.reduce((a, b) => a + b.rating, 0) / reviews.length).toFixed(1) : "0";
161	  const unreadCount = notifications.filter(n => !n.is_read).length;
162	
163	  const statusBadge = (status: string, arrived?: boolean) => {
164	    const styles: Record<string, string> = {
165	      active: "bg-[#E8F5E9] text-[#2D7A4F] border border-[#52C77F]/30",
166	      claimed: arrived ? "bg-[#FFF3E0] text-[#E65100] border border-[#FFB74D]/30" : "bg-[#E3F2FD] text-[#1565C0] border border-[#90CAF9]/30",
167	      completed: "bg-gray-100 text-gray-600 border border-gray-200",
168	      expired: "bg-red-50 text-red-500 border border-red-200",
169	    };
170	    const labels: Record<string, string> = {
