@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500;700&family=Plus+Jakarta+Sans:wght@500;700;800&display=swap');
@import "tailwindcss";

@theme {
  --font-sans: "Inter", ui-sans-serif, system-ui, sans-serif;
  --font-heading: "Plus Jakarta Sans", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, monospace;
  --color-brand: #2D7A4F;
  --color-brand-light: #52C77F;
  --color-brand-dark: #1a5a3e;
  --color-accent: #1565C0;
  --color-warning: #F5A623;
  --color-danger: #E53935;
}

body {
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  transition: background-color 0.3s, color 0.3s;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
}

/* Page transitions */
.page-enter { opacity: 0; transform: translateY(8px); }
.page-enter-active { opacity: 1; transform: translateY(0); transition: opacity 0.2s ease, transform 0.2s ease; }

/* Glass effect */
.glass { background: rgba(255, 255, 255, 0.7); backdrop-filter: blur(12px); }

/* Custom scrollbar */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 3px; }
html.dark ::-webkit-scrollbar-thumb { background: #475569; }

/* Card hover effect */
.card-hover { transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
.card-hover:hover { transform: translateY(-2px); box-shadow: 0 8px 25px rgba(0, 0, 0, 0.08); }

/* Gradient text */
.gradient-text { background: linear-gradient(135deg, #2D7A4F, #52C77F); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }

/* Pulse animation */
.live-pulse { animation: pulse-dot 2s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
@keyframes pulse-dot { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }

/* Skeleton loading */
.skeleton-shimmer { background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%); background-size: 200% 100%; animation: shimmer 1.5s ease-in-out infinite; }
@keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
html.dark .skeleton-shimmer { background: linear-gradient(90deg, #1e293b 25%, #334155 50%, #1e293b 75%); }

/* Focus ring */
.focus-ring { @apply focus:outline-none focus-visible:ring-2 focus-visible:ring-[#52C77F] focus-visible:ring-offset-2; }

/* ===== DARK MODE ===== */
/* Base */
html.dark { background-color: #0f172a; }
html.dark body { background-color: #0f172a !important; color: #f1f5f9 !important; }

/* Backgrounds */
html.dark .bg-white,
html.dark .bg-\[var\(--bg-secondary\)\] { background-color: #1e293b !important; }
html.dark .bg-\[\#F7F4EE\],
html.dark .min-h-screen,
html.dark .bg-\[var\(--bg-primary\)\] { background-color: #0f172a !important; }
html.dark .bg-\[\#F7F4EE\]\/80 { background-color: rgba(15, 23, 42, 0.8) !important; }
html.dark .bg-gray-50 { background-color: #1e293b !important; }
html.dark .bg-gray-100 { background-color: #334155 !important; }

/* Text colors */
html.dark .text-\[\#2C2C2C\],
html.dark .text-\[var\(--text-primary\)\] { color: #f1f5f9 !important; }
html.dark .text-gray-500,
html.dark .text-gray-600,
html.dark .text-\[var\(--text-secondary\)\] { color: #94a3b8 !important; }
html.dark .text-gray-700 { color: #cbd5e1 !important; }
html.dark .text-gray-400 { color: #64748b !important; }

/* Borders */
html.dark .border-gray-100,
html.dark .border-gray-200,
html.dark .border-\[var\(--border-color\)\] { border-color: #334155 !important; }
html.dark .border-gray-300 { border-color: #475569 !important; }

/* Gradient to-white overrides */
html.dark .from-gray-50 { --tw-gradient-from: #1e293b; }
html.dark .to-white { --tw-gradient-to: #1e293b; }
html.dark .via-white { --tw-gradient-via: #1e293b; }
html.dark .from-\[\#F7F4EE\] { --tw-gradient-from: #0f172a; }
html.dark .to-\[\#FFF8E1\] { --tw-gradient-to: #1e293b; }
html.dark .to-\[\#F0F8FF\] { --tw-gradient-to: #1e293b; }

/* Shadow overrides */
html.dark .shadow-sm { box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.3) !important; }
html.dark .shadow-md { box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3) !important; }
html.dark .shadow-lg { box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3) !important; }

/* Hero gradient overrides */
html.dark .from-yellow-50 { --tw-gradient-from: #1e293b !important; }
html.dark .to-orange-50 { --tw-gradient-to: #0f172a !important; }
html.dark .from-green-50 { --tw-gradient-from: #1e293b !important; }
html.dark .to-blue-50 { --tw-gradient-to: #0f172a !important; }
html.dark .via-white { --tw-gradient-via: #0f172a !important; }

/* CTA gradient overrides */
html.dark .from-\[\#F5A623\] { --tw-gradient-from: #b45309 !important; }
html.dark .to-\[\#F9A825\] { --tw-gradient-to: #d97706 !important; }

/* Logo circle gradient */
html.dark .from-\[\#F7F4EE\] { --tw-gradient-from: #1e293b !important; }

/* Special backgrounds */
html.dark .bg-\[\#E8F5E9\] { background-color: #1a3a2a !important; }
html.dark .bg-\[\#E3F2FD\] { background-color: #1a2a3a !important; }
html.dark .bg-\[\#FFF8E1\] { background-color: #2a2a1a !important; }
html.dark .bg-\[\#FFF3E0\] { background-color: #2a1f1a !important; }
html.dark .bg-\[\#F7F4EE\]\/50 { background-color: rgba(15, 23, 42, 0.5) !important; }

/* Problem/Solution card backgrounds */
html.dark .bg-red-50 { background-color: #2a1a1a !important; }
html.dark .border-red-100 { border-color: #4a2a2a !important; }
html.dark .bg-green-50 { background-color: #1a2a1a !important; }
html.dark .border-green-100 { border-color: #2a4a2a !important; }

/* Text brand colors stay visible */
html.dark .text-\[\#2D7A4F\],
html.dark .text-\[\#1565C0\],
html.dark .text-\[\#F5A623\],
html.dark .text-\[\#E53935\] { opacity: 1 !important; }

