@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500;700&family=Plus+Jakarta+Sans:wght@500;700;800&display=swap');
@import "tailwindcss";

@theme {
  --font-sans: "Inter", ui-sans-serif, system-ui, sans-serif;
  --font-heading: "Plus Jakarta Sans", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, monospace;
  --color-brand: #2D7A4F;
  --color-brand-light: #52C77F;
  --color-brand-dark: #1a5a3e;
  --color-accent: #1565C0;
  --color-warning: #F5A623;
  --color-danger: #E53935;
}

:root {
  --bg-primary: #F7F4EE;
  --bg-secondary: #ffffff;
  --text-primary: #2C2C2C;
  --text-secondary: #6B7280;
  --border-color: #E5E7EB;
}

body {
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  transition: background-color 0.3s, color 0.3s;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
}

/* Page transitions */
.page-enter { opacity: 0; transform: translateY(8px); }
.page-enter-active { opacity: 1; transform: translateY(0); transition: opacity 0.2s ease, transform 0.2s ease; }

/* Glass effect */
.glass { background: rgba(255, 255, 255, 0.7); backdrop-filter: blur(12px); }

/* Custom scrollbar */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 3px; }
html.dark ::-webkit-scrollbar-thumb { background: #475569; }

/* Card hover effect */
.card-hover { transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
.card-hover:hover { transform: translateY(-2px); box-shadow: 0 8px 25px rgba(0, 0, 0, 0.08); }

/* Gradient text */
.gradient-text { background: linear-gradient(135deg, #2D7A4F, #52C77F); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }

/* Pulse animation */
.live-pulse { animation: pulse-dot 2s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
@keyframes pulse-dot { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }

/* Skeleton loading */
.skeleton-shimmer { background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%); background-size: 200% 100%; animation: shimmer 1.5s ease-in-out infinite; }
