13	function AnimatedCounter({ target, suffix = "", className = "" }: { target: number; suffix?: string; className?: string }) {
14	  const [count, setCount] = useState(0);
15	  const ref = useRef<HTMLDivElement>(null);
16	  const done = useRef(false);
17	  useEffect(() => {
18	    const observer = new IntersectionObserver(([entry]) => {
19	      if (entry.isIntersecting && !done.current) {
20	        done.current = true;
21	        const duration = 1500, steps = 60, increment = target / steps;
22	        let current = 0;
23	        const timer = setInterval(() => { current += increment; if (current >= target) { setCount(target); clearInterval(timer); } else setCount(Math.floor(current)); }, duration / steps);
24	      }
25	    }, { threshold: 0.3 });
26	    if (ref.current) observer.observe(ref.current);
27	    return () => observer.disconnect();
28	  }, [target]);
29	  return <div ref={ref} className={`text-5xl font-bold mb-2 font-mono drop-shadow-md ${className}`}>{count}{suffix}</div>;
30	}
