@router.post("/donations/{donation_id}/arrived")
async def confirm_arrived(
    donation_id: int,
    session: SessionDep,
    current_user: User = Depends(get_current_user),
):
    if current_user.role != "donor":
        raise HTTPException(status_code=403, detail="Tidak punya akses")

    d = await session.execute(
        select(Donation).where(
            Donation.id == donation_id,
            Donation.status == "claimed",
            Donation.donor_id == current_user.id,
        )
    )
    d = d.scalar_one_or_none()
    if not d:
        raise HTTPException(status_code=404, detail="Donasi tidak ditemukan atau status tidak sesuai")

    d.arrived_at = datetime.now(UTC).isoformat()
    session.add(d)
    await session.commit()
    return {"message": "Kedatangan dikonfirmasi"}


