1	import { useState, useEffect } from "react";
2	import { MapContainer, TileLayer, Marker, Popup, Polyline } from "react-leaflet";
3	import { X, CheckCircle, Clock, MapPin, Hand } from "lucide-react";
4	import "leaflet/dist/leaflet.css";
5	import "../lib/mapIcons";
6	import { donorIcon, recipientIcon, courierIcon } from "../lib/mapIcons";
7	import { api } from "../lib/api";
8	import toast from "react-hot-toast";
9	
10	const SIMULATION_MS = 30000;
11	
12	export function LiveTrackingModal({ donation, user, onClose, onComplete }: any) {
13	  const [progress, setProgress] = useState(0);
14	  const [arrivalConfirmed, setArrivalConfirmed] = useState(false);
15	  const [confirming, setConfirming] = useState(false);
16	  const [done, setDone] = useState(false);
17	  const isDonor = user?.id === donation.donor_id;
18	
19	  useEffect(() => {
20	    let cancelled = false;
21	    api.fetchJSON(`/api/donations/${donation.id}`).then((d: any) => {
22	      if (cancelled) return;
23	      if (d.status === "completed") { setDone(true); return; }
24	      if (d.claimed_at) {
25	        const elapsed = Date.now() - new Date(d.claimed_at).getTime();
26	        if (elapsed >= SIMULATION_MS) setProgress(1);
27	        else setProgress(Math.max(0, elapsed / SIMULATION_MS));
28	      }
29	    }).catch(() => {});
30	    return () => { cancelled = true; };
31	  }, [donation.id]);
32	
33	  useEffect(() => {
34	    const timer = setInterval(() => {
35	      setProgress(p => {
36	         if (p >= 1) {
37	           clearInterval(timer);
38	           return 1;
39	         }
40	         return p + 0.005;
41	      });
42	    }, 150);
43	    return () => clearInterval(timer);
44	  }, []);
45	
46	  useEffect(() => {
47	    if (isDonor || done) return;
48	    const poll = setInterval(async () => {
49	      try {
50	        const d = await api.fetchJSON(`/api/donations/${donation.id}`);
51	        if (d.status === "completed") {
52	          setDone(true);
53	          clearInterval(poll);
54	          toast.success("Donor telah mengkonfirmasi serah terima!");
55	          setTimeout(() => { onComplete?.(); onClose(); }, 2000);
56	        }
57	      } catch {}
58	    }, 3000);
59	    return () => clearInterval(poll);
60	  }, [isDonor, done]);
61	
62	  const getLat = () => donation.donor_lat + (donation.recipient_lat - donation.donor_lat) * progress;
63	  const getLon = () => donation.donor_lon + (donation.recipient_lon - donation.donor_lon) * progress;
64	
65	  const center: [number, number] = [
66	    (donation.donor_lat + donation.recipient_lat) / 2,
67	    (donation.donor_lon + donation.recipient_lon) / 2
68	  ];
69	
70	  const handleConfirmArrival = async () => {
71	    setConfirming(true);
72	    try {
73	      await api.fetchJSON(`/api/donations/${donation.id}/complete`, { method: "POST" });
74	      setDone(true);
75	      toast.success("Serah terima berhasil dikonfirmasi!");
76	      setTimeout(() => { onComplete?.(); onClose(); }, 1500);
77	    } catch (err: any) {
78	      toast.error(err.message || "Gagal konfirmasi");
79	    } finally {
80	      setConfirming(false);
81	    }
82	  };
83	
84	  const arrived = progress >= 1;
85	
86	  return (
87	    <div className="fixed inset-0 z-[9999] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
88	       <div className="bg-white rounded-[2rem] w-full max-w-4xl shadow-2xl overflow-hidden flex flex-col border border-gray-100">
89	           <div className={`p-5 border-b flex justify-between items-center ${done ? 'bg-[#2D7A4F]' : arrived && !arrivalConfirmed ? 'bg-[#E65100]' : arrived ? 'bg-[#1565C0]' : 'bg-[#2D7A4F]'} text-white`}>
90	              <div>
91	                <div className="flex items-center gap-2">
92	                  {done ? (
93	                    <CheckCircle size={20} />
94	                  ) : (
95	                    <span className={`w-2 h-2 ${arrived ? 'bg-green-400' : 'bg-red-400'} rounded-full ${!arrived ? 'animate-pulse' : ''}`}></span>
96	                  )}
97	                  <h3 className="font-bold text-lg leading-tight">
98	                    {done ? "Pengiriman Selesai" : arrived && !arrivalConfirmed ? "Kurir Telah Sampai" : arrived ? "Tunggu Konfirmasi Serah Terima" : "Live Tracking Pengiriman"}
99	                  </h3>
100	                </div>
101	               <p className="text-sm opacity-80 mt-1">{donation.food_name}</p>
102	             </div>
103	             <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-full transition-colors"><X size={24}/></button>
104	          </div>
105	          <div className="h-[60vh] w-full bg-gray-100 relative">
106	             <MapContainer center={center} zoom={13} style={{ height: "100%", width: "100%" }}>
107	               <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" referrerPolicy="origin" />
108	               
109	                <Marker position={[donation.donor_lat, donation.donor_lon]} icon={donorIcon}>
110	                  <Popup><b>{donation.donor_name || "Lokasi Donor"}</b><br/>Titik Jemput</Popup>
111	                </Marker>
112	                
113	                <Marker position={[donation.recipient_lat, donation.recipient_lon]} icon={recipientIcon}>
114	                  <Popup><b>{donation.recipient_name || "Lokasi Penerima"}</b><br/>Tujuan</Popup>
115	                </Marker>
116	
117	               <Polyline positions={[
118	                 [donation.donor_lat, donation.donor_lon],
119	                 [donation.recipient_lat, donation.recipient_lon]
120	               ]} color="#2D7A4F" weight={4} dashArray="8, 8" opacity={0.6} />
121	
122	               {!done && (
123	                 <Marker position={[getLat(), getLon()]} icon={courierIcon} zIndexOffset={1000}>
124	                   <Popup>Kurir NUTRI-SHARE<br/>{(progress * 100).toFixed(0)}% Perjalanan Selesai</Popup>
125	                 </Marker>
126	               )}
127	             </MapContainer>
128	             
129	             {!done && (
130	               <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[1000] bg-white px-6 py-3 rounded-full shadow-lg border border-gray-100 flex items-center gap-4">
131	                  <div className="bg-gray-100 w-32 h-2 rounded-full overflow-hidden">
132	                     <div className="h-full bg-[#2D7A4F]" style={{ width: `${progress * 100}%` }}></div>
133	                  </div>
134	                  <span className="font-bold text-[#2D7A4F] text-sm whitespace-nowrap">{(progress * 100).toFixed(0)}% Selesai</span>
135	               </div>
136	             )}
137	          </div>
138	
139	           {arrived && !done && !arrivalConfirmed && (
140	             <div className="p-5 bg-[#FFF3E0] border-t border-[#FFB74D]">
141	               <div className="flex items-start justify-between gap-4">
142	                 <div className="flex items-start gap-3">
143	                   <MapPin className="text-[#E65100] mt-1 shrink-0" size={24} />
144	                   <div>
145	                     <p className="font-bold text-[#E65100] text-lg">Kurir telah sampai di tujuan</p>
146	                     <p className="text-sm text-gray-600">{donation.recipient_name || "Penerima"}</p>
147	                     {isDonor ? (
148	                       <p className="text-xs text-gray-500 mt-1">Konfirmasi bahwa kurir telah tiba</p>
149	                     ) : (
150	                       <p className="text-xs text-gray-500 mt-1">Menunggu donor mengkonfirmasi kedatangan kurir...</p>
151	                     )}
152	                   </div>
153	                 </div>
154	<div className="flex gap-2 shrink-0">
155	                    {isDonor && (
156	                      <button
157	                        onClick={async () => {
158	                          try {
159	                            await api.fetchJSON(`/api/donations/${donation.id}/arrived`, { method: "POST" });
160	                            setArrivalConfirmed(true);
161	                          } catch (err: any) {
162	                            toast.error(err.message || "Gagal konfirmasi kedatangan");
163	                          }
164	                        }}
165	                        className="bg-[#E65100] text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-opacity-90 shadow-md transition-all"
166	                      >
