@router.post("/recipient/emergency")
async def toggle_emergency(
    session: SessionDep,
    body: dict,
):
    user_id = body.get("user_id")
    if not user_id:
        raise HTTPException(status_code=400, detail="user_id required")

    rp = await session.execute(
        select(RecipientProfile).where(RecipientProfile.user_id == user_id)
    )
    rp = rp.scalar_one_or_none()
    if not rp:
        raise HTTPException(status_code=404, detail="Profil penerima tidak ditemukan")

    if rp.emergency == "active":
        raise HTTPException(
            status_code=400,
            detail="Status darurat sedang aktif, hubungi admin untuk menonaktifkan",
        )

    next_status = "pending" if rp.emergency == "none" else "none"
    rp.emergency = next_status
    session.add(rp)
    await session.commit()

